EXECUTE BLOCK AS
  DECLARE VARIABLE V_MOV INTEGER;
BEGIN
  IF ((SELECT COUNT(*) FROM EXTRATO_ITEM WHERE CONTROLE=46470 AND MOV_BANCARIO IS NULL)=1
      AND (SELECT COUNT(*) FROM CTARECEBER WHERE CONTROLE=744535 AND IDEMPRESA=1 AND MOV_BANCARIA IS NULL)=1) THEN
  BEGIN
    INSERT INTO MOV_BANCARIO
      (CDBANCO,AGENCIA,NUMCONTA,IDUSUARIO,IDEMPRESA,DESCRICAO,HISTORICO,DTLANCAMENTO,
       VALOR,TPLANCAMENTO,CDRECEBTO,STATUS,EXTRATO_ITEM,CONTROLE_CTA,SIST_ALT)
    VALUES (748,'4501','390143',1,1,'Conciliacao OFX','RECEBIMENTO PIX-PIX_CRED  46768704000100 BC CONSTRUCOES',TIMESTAMP '2026-06-10 00:00:00',
            18.00,0,29,0,46470,744535,'LOCAL')
    RETURNING CONTROLE INTO :V_MOV;
    UPDATE CTARECEBER SET MOV_BANCARIA=:V_MOV WHERE CONTROLE=744535 AND IDEMPRESA=1;
    UPDATE EXTRATO_ITEM SET MOV_BANCARIO=:V_MOV WHERE CONTROLE=46470;
  END
END^


